                if (JournalImpl.isInvalidSize(journalFileSize, wholeFileBuffer.position(), DataConstants.SIZE_BYTE)) {
                   reader.markAsDataFile(file);

                   wholeFileBuffer.position(pos + 1);
                   continue;
                }

                compactCount = wholeFileBuffer.get();
